mapper.select:
SELECT  FROM reference_releases WHERE dataset_key = #{dataset}
AND id < #{before}
ORDER BY id DESC LIMIT 50

SELECT child.code FROM reference_nodes child LEFT JOIN reference_nodes parent ON parent.release_id = child.release_id AND parent.code = child.parent_code WHERE child.release_id = #{id} AND child.level > 1 AND ( parent.code IS NULL
OR parent.level >= child.level OR parent.level != child.level - 1
) LIMIT 1

SELECT code, parent_code, level, name, CAST(source_metadata AS TEXT) AS source_metadata
FROM reference_nodes WHERE release_id = #{id}

  AND parent_code = #{parent}
  AND parent_code IS NULL

AND (strpos(name, #{query}) > 0 OR strpos(code, #{query}) = 1)
AND code > #{after}
ORDER BY code LIMIT #{limit}

SELECT id, release_id, previous_release_id, published_by, published_at
FROM reference_publications WHERE dataset_key = #{dataset}
AND id < #{before}
ORDER BY id DESC LIMIT 50
